use anyhow::{bail,Result};
use serde::{Deserialize,Serialize}; use serde_json::Value;
use std::{collections::{BTreeMap,BTreeSet},sync::{Arc,Mutex}};
#[derive(Clone,Debug,Serialize,Deserialize,PartialEq,Eq)]#[serde(rename_all="snake_case")]pub enum ActionKind{Cast,Attack,Move,Stop,UseItem,AcceptDuel,CancelDuel,Wait}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct ActionSpec{pub kind:ActionKind,pub ability:String,pub target:String}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Scope{pub mode:String,#[serde(default)]pub min_opponents:u32,#[serde(default)]pub max_opponents:u32}
#[derive(Clone,Debug)]pub enum Truth{False,True,Unknown}
#[derive(Clone,Debug)]pub enum Expr{Leaf{field:String,op:String,value:Value},All(Vec<Expr>),Any(Vec<Expr>),Not(Box<Expr>)}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct RuleDoc{pub id:String,pub owner:String,#[serde(default="default_enabled")]pub enabled:bool,pub priority:i32,#[serde(default="default_ttl")]pub ttl_ms:u64,pub when:Value,pub action:ActionSpec}
fn default_ttl()->u64{500}
fn default_enabled()->bool{true}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct PhaseDoc{pub id:String,#[serde(default)]pub min_hold_ms:u64,pub rules:Vec<RuleDoc>}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct PolicyDoc{pub schema_version:u32,pub revision:u64,pub enabled:bool,pub scope:Scope,#[serde(default)]pub predicates:BTreeMap<String,Value>,pub phases:Vec<PhaseDoc>}
#[derive(Clone,Debug)]pub struct Rule{pub doc:RuleDoc,pub expr:Expr}
#[derive(Clone,Debug)]pub struct Policy{pub doc:PolicyDoc,pub generation:u64,pub phases:BTreeMap<String,Vec<Rule>>}
#[derive(Clone,Debug,Default)]pub struct Observation{pub mode:String,pub phase:String,pub opponent_count:u32,pub numbers:BTreeMap<String,f64>,pub flags:BTreeMap<String,bool>,pub sets:BTreeMap<String,BTreeSet<u32>>,pub texts:BTreeMap<String,String>,pub targets:BTreeMap<String,u64>}
#[derive(Clone,Debug)]pub struct Candidate{pub rule:String,pub owner:String,pub action:ActionSpec,pub priority:i32,pub expires_ms:u64,pub generation:u64}
#[derive(Clone,Debug)]pub struct Trace{pub rule:String,pub eligible:bool,pub unknown:bool,pub reason:String}
fn allowed(s:&str)->bool{s.starts_with("self.")||s.starts_with("target.")||s.starts_with("nearby.")||s.starts_with("scene.")}
fn expr(v:&Value,preds:&BTreeMap<String,Value>,d:u32,n:&mut u32)->Result<Expr>{*n+=1;if d>8||*n>256{bail!("expression budget exceeded")};let o=v.as_object().ok_or_else(||anyhow::anyhow!("expression object"))?;if let Some(f)=o.get("field"){let f=f.as_str().ok_or_else(||anyhow::anyhow!("field"))?;if !allowed(f)||o.len()!=3{bail!("invalid leaf")};return Ok(Expr::Leaf{field:f.into(),op:o.get("op").and_then(Value::as_str).ok_or_else(||anyhow::anyhow!("op"))?.into(),value:o.get("value").unwrap().clone()})}if o.len()!=1{bail!("one operator")};if let Some(x)=o.get("not"){return Ok(Expr::Not(Box::new(expr(x,preds,d+1,n)?)))}for k in ["all","any"]{if let Some(x)=o.get(k){let a=x.as_array().ok_or_else(||anyhow::anyhow!("list"))?;if a.is_empty()||a.len()>32{bail!("list size")};let mut r=Vec::new();for y in a{r.push(expr(y,preds,d+1,n)?)}return Ok(if k=="all"{Expr::All(r)}else{Expr::Any(r)})}}if let Some(r)=o.get("ref"){let name=r.as_str().ok_or_else(||anyhow::anyhow!("ref"))?;return expr(preds.get(name).ok_or_else(||anyhow::anyhow!("missing ref"))?,preds,d+1,n)}bail!("unknown expression")}
fn truth(e:&Expr,o:&Observation)->Truth{match e{Expr::Leaf{field,op,value}=>{if let Some(x)=o.numbers.get(field){if let Some(y)=value.as_f64(){return cmp(*x,y,op)}}if let Some(x)=o.flags.get(field){if let Some(y)=value.as_bool(){return if(op=="eq"&&*x==y)||(op=="ne"&&*x!=y){Truth::True}else{Truth::False}}}if let Some(x)=o.texts.get(field){if let Some(y)=value.as_str(){return if(op=="eq"&&x==y)||(op=="ne"&&x!=y){Truth::True}else{Truth::False}}}if let Some(x)=o.sets.get(field){if let Some(y)=value.as_u64(){let b=x.contains(&(y as u32));return if op=="contains"{if b{Truth::True}else{Truth::False}}else if op=="not_contains"{if b{Truth::False}else{Truth::True}}else{Truth::Unknown}}}Truth::Unknown},Expr::Not(x)=>match truth(x,o){Truth::True=>Truth::False,Truth::False=>Truth::True,Truth::Unknown=>Truth::Unknown},Expr::All(xs)=>fold(xs,o,true),Expr::Any(xs)=>fold(xs,o,false)}}
fn cmp(x:f64,y:f64,op:&str)->Truth{let b=match op{"eq"=>x==y,"ne"=>x!=y,"lt"=>x<y,"lte"=>x<=y,"gt"=>x>y,"gte"=>x>=y,_=>return Truth::Unknown};if b{Truth::True}else{Truth::False}}
fn fold(xs:&[Expr],o:&Observation,all:bool)->Truth{let mut u=false;for x in xs{match truth(x,o){Truth::False if all=>return Truth::False,Truth::True if !all=>return Truth::True,Truth::Unknown=>u=true,_=>{}}}if u{Truth::Unknown}else if all{Truth::True}else{Truth::False}}
pub fn parse(text:&str)->Result<Policy>{if text.len()>1024*1024{bail!("policy too large")};let doc:PolicyDoc=serde_json::from_str(text)?;if doc.schema_version!=1||doc.phases.is_empty(){bail!("unsupported policy")};if doc.scope.min_opponents>doc.scope.max_opponents&&doc.scope.max_opponents!=0{bail!("scope")};let mut n=0;let mut phases=BTreeMap::new();for p in &doc.phases{let mut rs=Vec::new();for r in &p.rules{rs.push(Rule{doc:r.clone(),expr:expr(&r.when,&doc.predicates,0,&mut n)?})}phases.insert(p.id.clone(),rs);}Ok(Policy{doc,generation:0,phases})}
pub fn rank(p:&Policy,o:&Observation,now:u64,max:usize)->(Vec<Candidate>,Vec<Trace>){let mut c=Vec::new();let mut t=Vec::new();if !p.doc.enabled{return(c,t)}for r in p.phases.get(&o.phase).into_iter().flatten(){let m=truth(&r.expr,o);let tr=match m{Truth::True=>Trace{rule:r.doc.id.clone(),eligible:true,unknown:false,reason:"matched".into()},Truth::False=>Trace{rule:r.doc.id.clone(),eligible:false,unknown:false,reason:"condition_false".into()},Truth::Unknown=>Trace{rule:r.doc.id.clone(),eligible:false,unknown:true,reason:"unknown_observation".into()}};t.push(tr);if matches!(m,Truth::True)&&r.doc.enabled&&o.opponent_count>=p.doc.scope.min_opponents&&(p.doc.scope.max_opponents==0||o.opponent_count<=p.doc.scope.max_opponents){c.push(Candidate{rule:r.doc.id.clone(),owner:r.doc.owner.clone(),action:r.doc.action.clone(),priority:r.doc.priority,expires_ms:now+r.doc.ttl_ms,generation:p.generation})}}c.sort_by(|a,b|b.priority.cmp(&a.priority).then(a.rule.cmp(&b.rule)));c.truncate(if max==0{64}else{max.min(64)});(c,t)}
pub struct Store{active:Arc<Mutex<Arc<Policy>>>,pending:Mutex<Option<Policy>>,generation:Mutex<u64>}
impl Store{pub fn new(p:Policy)->Self{Self{active:Arc::new(Mutex::new(Arc::new(p))),pending:Mutex::new(None),generation:Mutex::new(0)}}pub fn stage(&self,text:&str)->Result<()>{*self.pending.lock().unwrap()=Some(parse(text)?);Ok(())}pub fn publish(&self)->Result<Arc<Policy>>{let mut p=self.pending.lock().unwrap().take().ok_or_else(||anyhow::anyhow!("no pending"))?;let mut g=self.generation.lock().unwrap();*g+=1;p.generation=*g;let a=Arc::new(p);*self.active.lock().unwrap()=a.clone();Ok(a)}pub fn current(&self)->Arc<Policy>{self.active.lock().unwrap().clone()}}
